import{_ as e,a,b as i,c as o,d as r,e as c,f as s,g as l,h as n,i as u,j as d,k as p,l as h,m}from"./chunks/gs_13.D_z1_q-r.js";import{_ as f,c as g,o as k,ae as q}from"./chunks/framework.Cd-3tpCq.js";const j=JSON.parse('{"title":"Getting Started","description":"Quickly start using MinecraftSounds to create your first music pack","frontmatter":{"title":"Getting Started","description":"Quickly start using MinecraftSounds to create your first music pack"},"headers":[],"relativePath":"en/guide/getting-started.md","filePath":"en/guide/getting-started.md"}'),b={name:"en/guide/getting-started.md"};function _(w,t,y,P,M,x){return k(),g("div",null,t[0]||(t[0]=[q('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>This guide will help you quickly get started with MinecraftSounds and create your first Minecraft music pack.</p><h2 id="installing-minecraftsounds-music-pack-generator" tabindex="-1">Installing MinecraftSounds Music Pack Generator <a class="header-anchor" href="#installing-minecraftsounds-music-pack-generator" aria-label="Permalink to &quot;Installing MinecraftSounds Music Pack Generator&quot;">​</a></h2><h3 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h3><ul><li>Windows 10 or above</li><li>1GB memory</li><li>500MB available disk space</li></ul><h3 id="download-minecraftsounds-music-pack-generator" tabindex="-1">Download MinecraftSounds Music Pack Generator <a class="header-anchor" href="#download-minecraftsounds-music-pack-generator" aria-label="Permalink to &quot;Download MinecraftSounds Music Pack Generator&quot;">​</a></h3><ol><li>Go to the <a href="/en/download.html">Download page</a> to get the latest version of the MinecraftSounds Music Pack Generator</li><li>Download the compressed file (e.g., MinecraftSounds.zip or MinecraftSounds.7z)</li><li>Extract the compressed file to your chosen directory (e.g., D:\\MinecraftSounds)</li></ol><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Please check if the extracted contents match the image <img src="'+e+'" alt="Extracted contents"></p></div><h2 id="creating-your-first-music-pack" tabindex="-1">Creating Your First Music Pack <a class="header-anchor" href="#creating-your-first-music-pack" aria-label="Permalink to &quot;Creating Your First Music Pack&quot;">​</a></h2><h3 id="launch-minecraftsounds-music-pack-generator" tabindex="-1">Launch MinecraftSounds Music Pack Generator <a class="header-anchor" href="#launch-minecraftsounds-music-pack-generator" aria-label="Permalink to &quot;Launch MinecraftSounds Music Pack Generator&quot;">​</a></h3><p>Start the application. On first launch, you will see a file format association prompt.</p><p><img src="'+a+'" alt="Create project"></p><p>Follow the prompts to associate the MinecraftSounds Music Pack Generator with the .mcsd file format.</p><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>After association is complete, you can directly double-click .mcsd files to open the program.</p></div><h3 id="create-a-new-project" tabindex="-1">Create a New Project <a class="header-anchor" href="#create-a-new-project" aria-label="Permalink to &quot;Create a New Project&quot;">​</a></h3><ol><li>Click the &quot;New Project&quot; button <img src="'+i+'" alt="Create project"></li><li>Fill in the information in the New Project window that appears <img src="'+o+'" alt="Create project"></li><li>After confirming the information is correct, click the &quot;Confirm&quot; button <img src="'+r+'" alt="Create project"></li><li>In the secondary confirmation dialog, click the &quot;Create&quot; button <img src="'+c+'" alt="Create project"></li><li>After the project is created, it will switch to the editing page. A &quot;Project created successfully&quot; dialog will appear; you can click &quot;OK&quot; to close it. <img src="'+s+'" alt="Create project"></li></ol><h3 id="adding-sound-effects" tabindex="-1">Adding Sound Effects <a class="header-anchor" href="#adding-sound-effects" aria-label="Permalink to &quot;Adding Sound Effects&quot;">​</a></h3><p>Now, you can start adding custom sound effects:</p><ol><li>Click the &quot;Select File&quot; button, and in the file selection window that appears, select the audio file you want to add <img src="'+l+'" alt="Create project"></li></ol><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Only .ogg, .wav, .mp3, and .flac audio file formats are supported</p></div><ol start="2"><li>The added audio files will be displayed in the list below, where you can view the audio files you&#39;ve added <img src="'+n+'" alt="Create project"></li></ol><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Minecraft officially only supports .ogg format audio files. When exporting, the program will automatically convert other formats to .ogg format.</p></div><h3 id="exporting-the-music-pack" tabindex="-1">Exporting the Music Pack <a class="header-anchor" href="#exporting-the-music-pack" aria-label="Permalink to &quot;Exporting the Music Pack&quot;">​</a></h3><p>When you are satisfied with your music pack, you can export it as a resource pack usable in Minecraft:</p><ol><li>Click the &quot;Export&quot; button in the top menu <img src="'+u+'" alt="Create project"></li><li>Click the &quot;Start Export&quot; button at the bottom, and the program will begin executing according to the steps above. <img src="'+d+'" alt="Create project"></li><li>After a successful export, a dialog will appear; click the &quot;OK&quot; button to close it. <img src="'+p+'" alt="Create project"></li><li>Click the &quot;Open Folder&quot; button in the lower left corner to open the folder containing the packaged audio pack <img src="'+h+'" alt="Create project"></li></ol><div class="warning custom-block"><p class="custom-block-title">Tip</p><p>If the program doesn&#39;t open the folder, you can find it through the path shown after &quot;Folder opened&quot;.<br> You can also find it at: <code>{software directory}\\_internal\\app\\projects\\{your music pack name}\\dist</code><img src="'+m+'" alt="Create project"></p></div><h2 id="installing-the-music-pack-in-minecraft" tabindex="-1">Installing the Music Pack in Minecraft <a class="header-anchor" href="#installing-the-music-pack-in-minecraft" aria-label="Permalink to &quot;Installing the Music Pack in Minecraft&quot;">​</a></h2><ol><li>Open Minecraft</li><li>Click &quot;Options&quot; → &quot;Resource Packs&quot;</li><li>Click &quot;Open Resource Pack Folder&quot;</li><li>Copy the exported .zip file to this folder</li><li>Return to Minecraft, your music pack should appear in the available resource packs list</li><li>Click the &quot;→&quot; button to move it to the &quot;Selected Resource Packs&quot; list</li><li>Click the &quot;Done&quot; button</li></ol><p>Now, you can use your custom sound effects or music in the game!</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li>Explore the <a href="/en/tutorials/">Tutorials</a> section to learn how to create more complex music packs</li></ul>',31)]))}const v=f(b,[["render",_]]);export{j as __pageData,v as default};
